 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support Contact</title>
   <style>
     :root {
       --bg: #f3f6fb;
       --panel: rgba(255, 255, 255, 0.92);
       --panel-border: rgba(148, 163, 184, 0.2);
       --text: #0f172a;
       --muted: #64748b;
       --accent: #2563eb;
       --accent-dark: #1d4ed8;
       --error: #dc2626;
       --input-bg: #ffffff;
       --shadow: 0 24px 80px rgba(15, 23, 42, 0.12);
       --radius: 22px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(37, 99, 235, 0.18), transparent 32%),
         radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.16), transparent 24%),
         linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
       display: grid;
       place-items: center;
       padding: 32px 20px;
     }

     .page-shell {
       width: min(100%, 1040px);
       display: grid;
       grid-template-columns: 1.05fr 0.95fr;
       gap: 28px;
       align-items: stretch;
     }

     .hero,
     .form-card {
       background: var(--panel);
       backdrop-filter: blur(14px);
       border: 1px solid var(--panel-border);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
     }

     .hero {
       padding: 44px;
       display: flex;
       flex-direction: column;
       justify-content: space-between;
       gap: 28px;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       padding: 8px 14px;
       border-radius: 999px;
       background: rgba(37, 99, 235, 0.08);
       color: var(--accent);
       font-size: 0.88rem;
       font-weight: 700;
       letter-spacing: 0.01em;
     }

     h1 {
       margin: 18px 0 14px;
       font-size: clamp(2.4rem, 5vw, 3.6rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .hero p {
       margin: 0;
       max-width: 34rem;
       font-size: 1.02rem;
       line-height: 1.7;
       color: var(--muted);
     }

     .support-points {
       display: grid;
       grid-template-columns: repeat(3, minmax(0, 1fr));
       gap: 14px;
     }

     .support-point {
       padding: 16px;
       border-radius: 18px;
       background: rgba(255, 255, 255, 0.75);
       border: 1px solid rgba(148, 163, 184, 0.16);
     }

     .support-point strong {
       display: block;
       margin-bottom: 6px;
       font-size: 0.95rem;
     }

     .support-point span {
       color: var(--muted);
       font-size: 0.92rem;
       line-height: 1.5;
     }

     .form-card {
       padding: 34px;
       display: flex;
       flex-direction: column;
       justify-content: center;
     }

     .form-header h2 {
       margin: 0 0 10px;
       font-size: 1.8rem;
       letter-spacing: -0.03em;
     }

     .form-header p {
       margin: 0 0 28px;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 20px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

     label {
       font-size: 0.94rem;
       font-weight: 700;
     }

     input {
       width: 100%;
       border: 1px solid rgba(148, 163, 184, 0.32);
       border-radius: 14px;
       background: var(--input-bg);
       color: var(--text);
       padding: 15px 16px;
       font: inherit;
       transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
     }

     input::placeholder {
       color: #94a3b8;
     }

     input:focus {
       outline: none;
       border-color: rgba(37, 99, 235, 0.7);
       box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
       transform: translateY(-1px);
     }

     .helper-text,
     .error-text {
       font-size: 0.88rem;
       line-height: 1.5;
     }

     .helper-text {
       color: var(--muted);
     }

     .error-text {
       color: var(--error);
       min-height: 1.2em;
       visibility: hidden;
     }

     .form-field.invalid input {
       border-color: rgba(220, 38, 38, 0.55);
       box-shadow: 0 0 0 4px rgba(220, 38, 38, 0.08);
     }

     .form-field.invalid .error-text {
       visibility: visible;
     }

     .submit-button {
       border: 0;
       border-radius: 14px;
       padding: 16px 20px;
       font: inherit;
       font-weight: 700;
       color: #ffffff;
       background: linear-gradient(135deg, var(--accent) 0%, #3b82f6 100%);
       cursor: pointer;
       transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
       box-shadow: 0 16px 30px rgba(37, 99, 235, 0.24);
     }

     .submit-button:hover {
       transform: translateY(-1px);
       background: linear-gradient(135deg, var(--accent-dark) 0%, var(--accent) 100%);
     }

     .submit-button:active {
       transform: translateY(0);
     }

     .status-message {
       margin: 4px 0 0;
       font-size: 0.92rem;
       color: #15803d;
       min-height: 1.4em;
     }

     @media (max-width: 900px) {
       .page-shell {
         grid-template-columns: 1fr;
       }

       .hero,
       .form-card {
         padding: 28px;
       }

       .support-points {
         grid-template-columns: 1fr;
       }
     }
   </style>
 </head>
 <body>
   <main class="page-shell">
     <section class="hero" aria-label="Support overview">
       <div>
         <span class="eyebrow">Product Support</span>
         <h1>Reach the team behind your next fix.</h1>
         <p>
           Send us the details and a support specialist will follow up with the right next step,
           whether you need troubleshooting help, account guidance, or product answers.
         </p>
       </div>

       <div class="support-points">
         <div class="support-point">
           <strong>Fast routing</strong>
           <span>Your request gets directed to the right specialist from the start.</span>
         </div>
         <div class="support-point">
           <strong>Clear updates</strong>
           <span>We follow up with the context and details you need to keep moving.</span>
         </div>
         <div class="support-point">
           <strong>Human response</strong>
           <span>Built for real support conversations, not generic ticket forms.</span>
         </div>
       </div>
     </section>

     <section class="form-card" aria-label="Contact support">
       <div class="form-header">
         <h2>Contact support</h2>
         <p>Tell us how to reach you and we’ll get back to you as soon as possible.</p>
       </div>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="fullName">Full name</label>
           <input
             id="fullName"
             name="fullName"
             type="text"
             autocomplete="name"
             placeholder="Jordan Lee"
             required
           >
           <p class="error-text" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="email">Email address</label>
           <input
             id="email"
             name="email"
             type="email"
             autocomplete="email"
             placeholder="jordan@company.com"
             required
           >
           <p class="error-text" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="phone">Phone number</label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             placeholder="+1 (555) 123-4567"
           >
           <p class="helper-text">Optional. Use digits with an optional country code, for example +1 (555) 123-4567.</p>
           <p class="error-text" aria-live="polite"></p>
         </div>

         <button class="submit-button" type="submit">Submit request</button>
         <p class="status-message" id="statusMessage" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("support-form");
     const statusMessage = document.getElementById("statusMessage");
     const fields = [
       {
         input: document.getElementById("fullName"),
         validate(value) {
           return value.trim() ? "" : "Please enter your full name.";
         }
       },
       {
         input: document.getElementById("email"),
         validate(value) {
           if (!value.trim()) {
             return "Please enter your email address.";
           }

           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
             ? ""
             : "Please enter a valid email address.";
         }
       },
       {
         input: document.getElementById("phone"),
         validate(value) {
           const trimmed = value.trim();

           if (!trimmed) {
             return "";
           }

           return /^[+]?[0-9()\-\s]{7,20}$/.test(trimmed)
             ? ""
             : "Use a phone number like +1 (555) 123-4567.";
         }
       }
     ];

     const showFieldState = (field, shouldShow) => {
       const formField = field.input.closest(".form-field");
       const error = formField.querySelector(".error-text");
       const message = field.validate(field.input.value);

       if (shouldShow && message) {
         formField.classList.add("invalid");
         error.textContent = message;
       } else {
         formField.classList.remove("invalid");
         error.textContent = "";
       }

       return !message;
     };

     fields.forEach((field) => {
       field.input.addEventListener("blur", () => {
         showFieldState(field, true);
       });

       field.input.addEventListener("input", () => {
         if (field.input.closest(".form-field").classList.contains("invalid")) {
           showFieldState(field, true);
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const isValid = fields.every((field) => showFieldState(field, true));

       if (!isValid) {
         statusMessage.textContent = "";
         return;
       }

       statusMessage.textContent = "Your message is ready to send. Our support team will reach out soon.";
       form.reset();
       fields.forEach((field) => showFieldState(field, false));
     });
   </script>
 </body>
 </html>

